class Solution:
    def numberOfBoomerangs(self, points: list[list[int]]) -> int:
        total = 0
        for i, (x, y) in enumerate(points):
            for j, (a, b) in enumerate(points):
                for k, (c, d) in enumerate(points):
                    if i != j and i != k and j != k and (a - x)**2 + (b - y)**2 == (c - x)**2 + (d - y)**2:
                        total += 1
        return total
